WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM payments), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT CASE WHEN session_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS session_id_tier, SUM(CASE WHEN status = 'REFUNDED' THEN session_start_flag ELSE 0 END) AS refunded_session_start_flag, MAX(paid_at) AS ended_at FROM islands GROUP BY CASE WHEN session_id >= 8 THEN 'LARGE' ELSE 'SMALL' END HAVING refunded_session_start_flag >= 0
